def sha256_file(path: str | Path, chunk: int = CHUNK) -> str:
    """Streaming SHA-256 over raw bytes."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            block = f.read(chunk)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


